import sys

def main():
    data = sys.stdin.read().splitlines()
    if not data:
        return

    n = int(data[0].strip())
    rounds = []

    for i in range(1, n + 1):
        parts = data[i].split()
        name = parts[0]
        score = int(parts[1])
        rounds.append((name, score))

    scores = {}
    for name, score in rounds:
        if name not in scores:
            scores[name] = 0
        scores[name] += score

    max_score = max(scores.values())

    candidates = {name for name, total in scores.items() if total == max_score}

    current_scores = {}
    for name, score in rounds:
        if name in candidates:
            current_scores[name] = current_scores.get(name, 0) + score
            if current_scores[name] >= max_score:
                print(name)
                return

if __name__ == "__main__":
    main()
